class Solution {
    public long singleDivisorTriplet(int[] nums) {
        long[] f = new long[101];
        for (int x : nums) f[x]++;
        long ans = 0;
        for (int a = 1; a <= 100; a++) {
            if (f[a] == 0) continue;
            for (int b = 1; b <= 100; b++) {
                if (f[b] == 0) continue;
                for (int c = 1; c <= 100; c++) {
                    if (f[c] == 0) continue;
                    int s = a + b + c;
                    int divs = (s % a == 0 ? 1 : 0) + (s % b == 0 ? 1 : 0) + (s % c == 0 ? 1 : 0);
                    if (divs != 1) continue;
                    long ways;
                    if (a == b && b == c) ways = f[a] * (f[a] - 1) * (f[a] - 2);
                    else if (a == b) ways = f[a] * (f[a] - 1) * f[c];
                    else if (a == c) ways = f[a] * (f[a] - 1) * f[b];
                    else if (b == c) ways = f[a] * f[b] * (f[b] - 1);
                    else ways = f[a] * f[b] * f[c];
                    ans += ways;
                }
            }
        }
        return ans;
    }
}
